// GET /users?status=active&page=0
@GetMapping
public List<User> getUsers(
    @RequestParam String status,
    @RequestParam(defaultValue = "0") int page) { ... }

@PostMapping
@ResponseStatus(HttpStatus.CREATED)  // returns 201
public User createUser(@Valid @RequestBody CreateUserRequest req) {
    return userService.create(req);
}

public class CreateUserRequest {
    @NotBlank
    private String name;
    @Email
    private String email;
    // getters, setters
}

@PostMapping
@ResponseStatus(HttpStatus.CREATED)  // always 201
public User create(@RequestBody User user) { ... }

@GetMapping("/{id}")
public ResponseEntity<User> get(@PathVariable Long id) {
    return userService.findById(id)
        .map(ResponseEntity::ok)              // 200 if found
        .orElse(ResponseEntity.notFound().build()); // 404 if not
}

@RestControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(ResourceNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public ErrorResponse handleNotFound(ResourceNotFoundException ex) {
        return new ErrorResponse("NOT_FOUND", ex.getMessage());
    }
    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public ErrorResponse handleValidation(MethodArgumentNotValidException ex) {
        return new ErrorResponse("VALIDATION_ERROR", ex.getMessage());
    }
}

@RestController
@RequestMapping("/api/v1/users")  // base path for all methods
