    @GetMapping          // GET /api/v1/users
    public List<User> getAll() { ... }
    @GetMapping("/{id}") // GET /api/v1/users/42
    public User getOne(@PathVariable Long id) { ... }
    @PostMapping         // POST /api/v1/users
    public User create(@RequestBody User u) { ... }
}
